// Extrai o SQL do GitHub (pode vir como string direta ou em .data)
const schemaText = $input.first().json?.data ?? $input.first().json ?? '';
if (!schemaText || String(schemaText).trim().length < 100) {
  throw new Error('Schema SQL inválido ou vazio — verifique C8_SCHEMA_RAW_URL e GITHUB_TOKEN');
}

// Lê client_id do body (opcional — null = modo massa)
const body = $('Webhook — Trigger Manual').first().json?.body ?? $('Webhook — Trigger Manual').first().json ?? {};
const clientId = (body.client_id ?? '').toString().trim() || null;

console.log(clientId ? `Modo individual: ${clientId}` : 'Modo massa: todos os clientes');
return [{ json: { client_id: clientId, schema_sql: String(schemaText) } }];

// Recebe a lista de clientes do Banco A
const raw = $input.first().json;
let clients = Array.isArray(raw) ? raw : (raw ?? []);

// Filtra apenas clientes com credenciais completas
clients = clients.filter(c => c.supabase_url && c.service_key);

// Se for modo individual, filtra pelo client_id
const clientId = $('Preparar Schema e Modo').first().json.client_id;
if (clientId) {
  clients = clients.filter(c => c.client_id === clientId);
  if (clients.length === 0) {
    throw new Error(`Cliente ${clientId} não encontrado ou sem credenciais (supabase_url + service_key obrigatórios).`);
  }
}

const schemaSql = $('Preparar Schema e Modo').first().json.schema_sql;
console.log(`Clientes para atualização: ${clients.length}`);

// Propaga schema_sql para cada item — cada item vira uma execução paralela no próximo nó
return clients.map(c => ({ json: { ...c, schema_sql: schemaSql } }));

// Para cada cliente: delega aplicação do schema para a Edge Function provision-client-db
// Essa Edge Function:
//   1. Faz bootstrap do exec_sql via /pg/query se banco zerado
//   2. Aplica o bank_b_full_schema.sql (usa a cópia inline da Edge Function)
//   3. Faz seed dos estágios do pipeline
//
// O schema_sql vindo do GitHub é a fonte de verdade — mas como a Edge Function
// usa sua própria cópia inline, passamos o client_id para ela resolver internamente.
// Para forçar uso do schema do GitHub, seria necessário passá-lo no body.

const { client_id, supabase_url, service_key, client_name } = $json;

const supabaseAUrl = $env.SUPABASE_URL.replace(/\/$/, '');
const serviceKeyA  = $env.SUPABASE_SERVICE_KEY;

try {
  const res = await fetch(`${supabaseAUrl}/functions/v1/provision-client-db`, {
    method: 'POST',
    headers: {
      'Content-Type':  'application/json',
      'apikey':        serviceKeyA,
      'Authorization': `Bearer ${serviceKeyA}`,
    },
    body: JSON.stringify({ client_id }),
  });

  const data = await res.json().catch(() => ({}));

  if (res.ok && data.success !== false) {
    console.log(`✅ ${client_name ?? client_id}: schema aplicado`);
    return [{ json: { success: true, client_id, client_name: client_name ?? client_id, message: data.message ?? 'Schema aplicado.' } }];
  } else {
    const err = data.error ?? data.message ?? `HTTP ${res.status}`;
    console.error(`❌ ${client_name ?? client_id}: ${err}`);
    return [{ json: { success: false, client_id, client_name: client_name ?? client_id, error: err } }];
  }
} catch (e) {
  console.error(`❌ ${client_name ?? client_id}: ${e.message}`);
  return [{ json: { success: false, client_id, client_name: client_name ?? client_id, error: e.message } }];
}

const results = $input.all();
const total   = results.length;
const success = results.filter(r => r.json.success === true).length;
const failed  = total - success;
const failures = results
  .filter(r => r.json.success !== true)
  .map(r => ({ client_id: r.json.client_id ?? 'desconhecido', client_name: r.json.client_name, error: r.json.error }));

if (failures.length > 0) console.error('Falhas:', JSON.stringify(failures));
console.log(`Resultado: ${success}/${total} sucesso, ${failed} falha(s)`);

return [{ json: { total, success, failed, failures, updated_at: new Date().toISOString() } }];
